from ops.testkit import DaemonRefused,World
token='a528-race-'+uuid.uuid4().hex;w=World(host_path=False);foreign_box=[]
def launch_foreign():
 time.sleep(.05);foreign_box.append(subprocess.Popen([sys.executable,'-c','import time;time.sleep(30)',token],stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True))
t=threading.Thread(target=launch_foreign);t.start()
